#include <stdio.h>
#include <string.h>
#include <ctype.h>

static const struct {
    int   value;
    const char *sym;
} conv_table[] = {
    {1000, "M"},
    { 900, "CM"},
    { 500, "D"},
    { 400, "CD"},
    { 100, "C"},
    {  90, "XC"},
    {  50, "L"},
    {  40, "XL"},
    {  10, "X"},
    {   9, "IX"},
    {   5, "V"},
    {   4, "IV"},
    {   1, "I"},
    {   0, NULL}
};

static int char_to_val(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

static void int_to_roman(int n, char *out)
{
    char *p = out;
    for (size_t i = 0; conv_table[i].value > 0; ++i) {
        while (n >= conv_table[i].value) {
            const char *s = conv_table[i].sym;
            while (*s) *p++ = *s++;
            n -= conv_table[i].value;
        }
    }
    *p = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *src = argv[1];
    size_t len = strlen(src);
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }

    char input_up[64];
    for (size_t i = 0; i < len; ++i) {
        input_up[i] = (char)toupper((unsigned char)src[i]);
    }
    input_up[len] = '\0';

    int total = 0;
    for (size_t i = 0; i < len; ++i) {
        int v = char_to_val(input_up[i]);
        if (v < 0) {
            puts("INVALID");
            return 0;
        }
        if (i + 1 < len) {
            int v_next = char_to_val(input_up[i + 1]);
            if (v_next < 0) {
                puts("INVALID");
                return 0;
            }
            if (v < v_next)
                total -= v;
            else
                total += v;
        } else {
            total += v;
        }
    }

    if (total <= 0 || total > 3999) {
        puts("INVALID");
        return 0;
    }

    char canonical[64];
    int_to_roman(total, canonical);
    if (strcmp(canonical, input_up) != 0) {
        puts("INVALID");
        return 0;
    }

    printf("%d\n", total);
    return 0;
}
